-- QualiSphere Beta only: initial company configuration; no user access or operational records.
DO $guard$
BEGIN
 IF EXISTS(SELECT 1 FROM public.tenants) OR EXISTS(SELECT 1 FROM auth.users)
 OR EXISTS(SELECT 1 FROM public.security_roles)
 OR has_schema_privilege('authenticated','public','USAGE') THEN
  RAISE EXCEPTION 'Company preparation requires the unconfigured, locked sandbox';
 END IF;
END;
$guard$;
