horized for SCAR approval tasks when assigned.","is_assignable":true,"is_active":true,"is_system_role":true,"permission_key":"scar_approver"},{"code":"scar_coordinator","label":"SCAR Coordinator","category":"SCAR","description":"Coordinate supplier corrective action workflows.","is_assignable":true,"is_active":true,"is_system_role":true,"permission_key":"scar_coordinator"},{"code":"scar_user","label":"SCAR User","category":"SCAR","description":"Standard SCAR module access.","is_assignable":true,"is_active":true,"is_system_role":true,"permission_key":"scar_user"},{"code":"training_administrator","label":"Training Administrator","category":"Training","description":"Administer training configuration and assignments.","is_assignable":true,"is_active":true,"is_system_role":true,"permission_key":"training_administrator"},{"code":"training_coordinator","label":"Training Coordinator","category":"Training","description":"Coordinate training activities.","is_assignable":true,"is_active":true,"is_system_role":true,"permission_key":"training_coordinator"},{"code":"training_user","label":"Training User","category":"Training","description":"Standard Training module access.","is_assignable":true,"is_active":true,"is_system_role":true,"permission_key":"training_user"},{"code":"vp_quality","label":"VP Quality","category":"System","description":"Enterprise VP Quality authority.","is_assignable":true,"is_active":true,"is_system_role":true,"permission_key":"vp_quality"}]$roles$::jsonb)
