DO $provision$
DECLARE v_tenant uuid;
BEGIN
 INSERT INTO public.tenants(tenant_code,company_name,slug,status,is_internal,country_code,default_timezone,created_by)
 VALUES('QUALISPHERE-SANDBOX','QualiSphere Sandbox','qualisphere-sandbox','provisioning',false,'US','America/Chicago','sandbox_setup')
 RETURNING id INTO v_tenant;
 INSERT INTO public.company_settings(tenant_id,company_name,timezone,enable_notifications,enable_overdue_scan,enable_email_notifications)
 VALUES(v_tenant,'QualiSphere Sandbox','America/Chicago',false,false,false);
 INSERT INTO public.tenant_module_access(tenant_id,module_code,is_enabled,enabled_by)
 SELECT v_tenant,code,false,'sandbox_setup'
 FROM unnest(ARRAY['ncmr','capa','scar','change_control','controlled_documents','training','equipment','audit','management_review','complaints','oos_oot']) AS code;
END;
$provision$;

